import { useEffect } from 'react';
export function useCameraSessionIsRunning(session, isActive) {
    useEffect(() => {
        if (session == null)
            return;
        const load = async () => {
            if (isActive) {
                await session.start();
            }
            else {
                await session.stop();
            }
        };
        load();
    }, [isActive, session]);
}
